//! verified/harness/ut_incremental.rs -- the simple / incremental /
//! block-boundary dispatch equivalence theorems
//! (reference organization: #[path] pulls in the verified/src modules,
//! the spec-side facts are not copied)
//!
//! [Origin Rust: tests.rs test_hash_simple / test_hash_incremental + tests128.rs namesakes (pin 2fcf2a7, code/src/tests.rs)]
//! Proof shape: staged bv sealing (one bv step per spec-chain link,
//! literal state tuples,
//! single-level application) + function congruence propagation along the
//! exec ensures chain + an equality closing step;
//! the literals are re-computed by an isomorphic Python model and
//! machine-checked by Z3 (the official vectors are the final expected
//! values, not the Python model's).

#[path = "../src/common.rs"]
mod common;
#[path = "../src/sip.rs"]
mod sip;
#[path = "../src/sip128.rs"]
mod sip128;

use vstd::prelude::*;

verus! {
use crate::sip::*;
use crate::sip128::*;
use crate::common::compress_spec;


/* ============================================================
 * tests.rs test_hash_simple (line 304) / test_hash_incremental (line 313)
 * and the tests128.rs namesakes (lines 106/114) -- strengthened:
 * write_u64(X) == write_u8(LE(X) written out eight times)
 * (block-boundary cross-dispatch equivalence:
 * one side compresses through the short_write else branch, the other
 * accumulates the tail and triggers the compression on fill).
 * Additionally: the key of test_hash_simple = new_with_key(1..16).
 * ============================================================ */
pub exec fn th_simple13_123() -> (r: u64)
    ensures r == 0xb5fd6297eeacffdcu64  // model re-computation (Z3-checked)
{
    let mut h = Hasher13::new_with_keys(0x0807060504030201u64, 0x100f0e0d0c0b0a09u64);
    h.write_u8(1u8); h.write_u8(2u8); h.write_u8(3u8);
    let r0 = h.finish();
    proof {
    assert(spec_new_13(0x0807060504030201u64, 0x100f0e0d0c0b0a09u64) == (0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 0u64, 0u64, 0u64)) by(bit_vector); // reset
    assert(spec_write_u8_13((0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 0u64, 0u64, 0u64), 1u8) == (0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 1u64, 1u64, 1u64)) by(bit_vector); // u8 1u8
    assert(spec_write_u8_13((0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 1u64, 1u64, 1u64), 2u8) == (0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 2u64, 0x0000000000000201u64, 2u64)) by(bit_vector); // u8 2u8
    assert(spec_write_u8_13((0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 2u64, 0x0000000000000201u64, 2u64), 3u8) == (0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 3u64, 0x0000000000030201u64, 3u64)) by(bit_vector); // u8 3u8
    assert(spec_finish_13((0x0807060504030201u64, 0x100f0e0d0c0b0a09u64, 0x7b686b6074706774u64, 0x74607c6c626f6564u64, 0x647e61606a667060u64, 0x646a6a6f757f6f7au64, 3u64, 0x0000000000030201u64, 3u64)) == 0xb5fd6297eeacffdcu64) by(bit_vector); // finish whole chain
    assert(r0 == 0xb5fd6297eeacffdcu64);
    }
    r0
}

/// write_u64(X) == write_u8 x8 (LE bytes); both sides close onto the same
/// official vector
pub exec fn th_equiv24_u64_vs_u8fold() -> (r: bool)
    ensures r == true
{
    let mut ha = Hasher24::new_with_keys(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64);
    ha.write_u64(0x0706050403020100u64);
    let ra = ha.finish();
    let mut hb = Hasher24::new_with_keys(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64);
    hb.write_u8(0u8); hb.write_u8(1u8); hb.write_u8(2u8); hb.write_u8(3u8);
    hb.write_u8(4u8); hb.write_u8(5u8); hb.write_u8(6u8); hb.write_u8(7u8);
    let rb = hb.finish();
    proof {
    // Path A: a single write_u64
    assert(spec_new_24(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64)) by(bit_vector); // reset
    assert(spec_write_u64_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64), 0x0706050403020100u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x4a017198de0a59e0u64, 0x0d52f6f62a4f59a4u64, 0x634cb3577b01fd3du64, 0xa5224d6f55c7d9c8u64, 8u64, 0u64, 0u64)) by(bit_vector); // u64 0x0706050403020100u64
    assert(spec_finish_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x4a017198de0a59e0u64, 0x0d52f6f62a4f59a4u64, 0x634cb3577b01fd3du64, 0xa5224d6f55c7d9c8u64, 8u64, 0u64, 0u64)) == 0x93f5f5799a932462u64) by(bit_vector);
    assert(ra == 0x93f5f5799a932462u64);
    // Path B: eight consecutive write_u8
    assert(spec_new_24(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64)) by(bit_vector); // reset
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64), 0u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 1u64, 0u64, 1u64)) by(bit_vector); // u8 0u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 1u64, 0u64, 1u64), 1u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 2u64, 0x0000000000000100u64, 2u64)) by(bit_vector); // u8 1u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 2u64, 0x0000000000000100u64, 2u64), 2u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 3u64, 0x0000000000020100u64, 3u64)) by(bit_vector); // u8 2u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 3u64, 0x0000000000020100u64, 3u64), 3u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 4u64, 0x0000000003020100u64, 4u64)) by(bit_vector); // u8 3u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 4u64, 0x0000000003020100u64, 4u64), 4u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 5u64, 0x0000000403020100u64, 5u64)) by(bit_vector); // u8 4u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 5u64, 0x0000000403020100u64, 5u64), 5u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 6u64, 0x0000050403020100u64, 6u64)) by(bit_vector); // u8 5u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 6u64, 0x0000050403020100u64, 6u64), 6u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 7u64, 0x0006050403020100u64, 7u64)) by(bit_vector); // u8 6u8
    assert(spec_write_u8_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e6665u64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 7u64, 0x0006050403020100u64, 7u64), 7u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x4a017198de0a59e0u64, 0x0d52f6f62a4f59a4u64, 0x634cb3577b01fd3du64, 0xa5224d6f55c7d9c8u64, 8u64, 0u64, 0u64)) by(bit_vector); // u8 7u8
    assert(spec_finish_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x4a017198de0a59e0u64, 0x0d52f6f62a4f59a4u64, 0x634cb3577b01fd3du64, 0xa5224d6f55c7d9c8u64, 8u64, 0u64, 0u64)) == 0x93f5f5799a932462u64) by(bit_vector);
    assert(rb == 0x93f5f5799a932462u64);
    }
    ra == rb
}

/// 128-bit: write_u64(X) == write_u8 x8 (h1/h2 closed on both sides)
pub exec fn th_equiv128_u64_vs_u8fold() -> (r: bool)
    ensures r == true
{
    let mut ha = Hasher128_24::new_with_keys(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64);
    ha.write_u64(0x0706050403020100u64);
    let fa = ha.finish128();
    let mut hb = Hasher128_24::new_with_keys(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64);
    hb.write_u8(0u8); hb.write_u8(1u8); hb.write_u8(2u8); hb.write_u8(3u8);
    hb.write_u8(4u8); hb.write_u8(5u8); hb.write_u8(6u8); hb.write_u8(7u8);
    let fb = hb.finish128();
    proof {
    assert(spec_new_128_24(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64)) by(bit_vector); // reset
    assert(spec_write_u64_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64), 0x0706050403020100u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0xcab17422de0a5832u64, 0xed5036c15e6adbc8u64, 0x1ad531357b024c1du64, 0x799248d555c7dc22u64, 8u64, 0u64, 0u64)) by(bit_vector); // u64 0x0706050403020100u64
    assert(spec_finish128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0xcab17422de0a5832u64, 0xed5036c15e6adbc8u64, 0x1ad531357b024c1du64, 0x799248d555c7dc22u64, 8u64, 0u64, 0u64)) == (0x61f55862baa9623bu64, 0xb49714f364e2830fu64)) by(bit_vector);
    assert(fa.h1 == 0x61f55862baa9623bu64 && fa.h2 == 0xb49714f364e2830fu64);
    assert(spec_new_128_24(0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64)) by(bit_vector); // reset
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 0u64, 0u64, 0u64), 0u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 1u64, 0u64, 1u64)) by(bit_vector); // u8 0u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 1u64, 0u64, 1u64), 1u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 2u64, 0x0000000000000100u64, 2u64)) by(bit_vector); // u8 1u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 2u64, 0x0000000000000100u64, 2u64), 2u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 3u64, 0x0000000000020100u64, 3u64)) by(bit_vector); // u8 2u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 3u64, 0x0000000000020100u64, 3u64), 3u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 4u64, 0x0000000003020100u64, 4u64)) by(bit_vector); // u8 3u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 4u64, 0x0000000003020100u64, 4u64), 4u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 5u64, 0x0000000403020100u64, 5u64)) by(bit_vector); // u8 4u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 5u64, 0x0000000403020100u64, 5u64), 5u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 6u64, 0x0000050403020100u64, 6u64)) by(bit_vector); // u8 5u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 6u64, 0x0000050403020100u64, 6u64), 6u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 7u64, 0x0006050403020100u64, 7u64)) by(bit_vector); // u8 6u8
    assert(spec_write_u8_128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0x7469686173716475u64, 0x6b617f6d656e668bu64, 0x6b7f62616d677361u64, 0x7b6b696e727e6c7bu64, 7u64, 0x0006050403020100u64, 7u64), 7u8) == (0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0xcab17422de0a5832u64, 0xed5036c15e6adbc8u64, 0x1ad531357b024c1du64, 0x799248d555c7dc22u64, 8u64, 0u64, 0u64)) by(bit_vector); // u8 7u8
    assert(spec_finish128_24((0x0706050403020100u64, 0x0f0e0d0c0b0a0908u64, 0xcab17422de0a5832u64, 0xed5036c15e6adbc8u64, 0x1ad531357b024c1du64, 0x799248d555c7dc22u64, 8u64, 0u64, 0u64)) == (0x61f55862baa9623bu64, 0xb49714f364e2830fu64)) by(bit_vector);
    assert(fb.h1 == 0x61f55862baa9623bu64 && fb.h2 == 0xb49714f364e2830fu64);
    }
    fa.h1 == fb.h1 && fa.h2 == fb.h2
}

} // verus!

